package com.csust.eyediagnosis.workflow.evidence;
import org.junit.jupiter.api.Test; import java.util.LinkedHashSet; import java.util.Set; import static org.junit.jupiter.api.Assertions.*;
class EvidenceRetrievalIntentTest { @Test void canonicalizesAndBoundsControlledIntent() { LinkedHashSet<String> codes = new LinkedHashSet<>(Set.of("glaucoma", "amd")); EvidenceRetrievalIntent intent = new EvidenceRetrievalIntent("wf", 0, codes, Set.of("DISEASE_OVERVIEW"), RetrievalPurpose.DIAGNOSIS_EVIDENCE, 5); codes.add("myopia"); assertEquals(Set.of("amd", "glaucoma"), intent.diseaseCodes()); assertThrows(UnsupportedOperationException.class, () -> intent.diseaseCodes().add("myopia")); assertThrows(RuntimeException.class, () -> new EvidenceRetrievalIntent("wf", 0, Set.of("?"), Set.of("DISEASE_OVERVIEW"), RetrievalPurpose.DIAGNOSIS_EVIDENCE, 1)); } }
